(* [comment removed for export] *)
Ltac aapp_fact H ::=
  lazymatch type of H with
  | aapp ?A0 ?n0 =>
    let A1 := eval cbn [blk_addr blk_size fst snd] in A0 in
    let A := eval unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in A1 in
    let n1 := eval cbn [blk_addr blk_size fst snd] in n0 in
    let n := eval unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in n1 in
    lazymatch goal with
    | _ : aapp_seen A n |- _ => idtac
    | _ =>
      let K := fresh "APP" in let K2 := fresh "APQ" in let M := fresh "APPs" in
      first
        [ pose proof (aapp_num2 _ _ H ltac:(cbn [blk_addr blk_size fst snd]; unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *;
                                         rewrite ?fsz_1, ?fsz_4;
                                         first [ lia_t1
                                               | apply (Z.le_trans 0 64); [lia_t1| apply fsz_pos; lia_t1]
                                               | unfold fsz, fshn in *;
                                                 repeat match goal with |- context [2 ^ ?k] =>
                                                   lazymatch goal with _ : 0 <= 2 ^ k |- _ => fail | _ => pose proof (Z.pow_nonneg 2 k ltac:(lia_t1)) end end;
                                                 lia_t1 ])) as K
        | pose proof (aapp_num0 _ _ H) as K ];
      cbn [blk_addr blk_size fst snd] in K; unfold nsh, AFS_SIZE, AFS_HDR, AFS_FLAGS in K;
      rewrite ?fsz_1, ?fsz_4 in K; fold_nsh_lits K;
      destruct K as [K K2];
      lazymatch type of K with ?P => change P with (placed A n P) in K end;
      pose proof (I : aapp_seen A n) as M
    end
  end.

(* [comment removed for export] *)
Ltac aapp_win ::=
  first [ assumption
        | match goal with
          | K : aapp ?A ?n |- aapp (?A - ?A mod 8) _ => solve [cbn [cells_size csize Nat.add]; apply (aapp_granule_sub A n _ K); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; lia_arith]
          | K : aapp ?A ?n |- _ => solve [cbn [cells_size csize Nat.add]; apply (aapp_sub A n _ _ K); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
          | K : aapp ?A ?n /\ _ |- _ => solve [cbn [cells_size csize Nat.add]; apply (aapp_sub A n _ _ (proj1 K)); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
          | K : _ /\ aapp ?A ?n |- _ => solve [cbn [cells_size csize Nat.add]; apply (aapp_sub A n _ _ (proj2 K)); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
          | K : ablock_range _ ?A ?n |- _ =>
              solve [cbn [cells_size csize Nat.add]; apply (aapp_sub A n _ _ (proj2 (proj2 (proj2 (proj2 (proj2 (proj2 K))))))); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
          end ].

(* [comment removed for export] *)
Ltac inapp_via_aapp :=
  match goal with
  | K : aapp ?A ?n |- in_app_mem _ _ => solve [apply (aapp_in_app_mem A n _ _ K); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : aapp ?A ?n /\ _ |- in_app_mem _ _ => solve [apply (aapp_in_app_mem A n _ _ (proj1 K)); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : _ /\ aapp ?A ?n |- in_app_mem _ _ => solve [apply (aapp_in_app_mem A n _ _ (proj2 K)); unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *; rewrite ?fsz_1, ?fsz_4 in *; lia_arith]
  | K : aapp ?A ?n |- in_app_mem _ _ => solve [apply (aapp_in_app_mem _ _ _ _ (aapp_granule_sub A n _ K ltac:(lia_arith))); lia_arith]
  end.
Ltac inapp_win ::=
  first [ inapp_via_aapp
        | solve [right; n8b; unfold AFS_SIZE, AFS_HDR in *; lia]
        | solve [left; unfold ASHADOW_BASE in *; n8b; unfold AFS_SIZE, AFS_HDR in *; lia]
        | solve [unfold in_app_mem, ASHADOW_BASE in *; n8b; lia] ].

(* [comment removed for export] *)
Ltac shdisj_win :=
  first [ apply aapp_disjoint_sh; [lia| lia| n8b; lia| lia]
        | apply or_comm; apply aapp_disjoint_sh; [lia| lia| n8b; lia| lia] ].

(* [comment removed for export] *)
Ltac lia ::=
  unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *;
  first [ lazymatch goal with
          | |- aapp _ _ => aapp_win
          | |- _ /\ _ => split; lia
          end
        | lia_t1
        | progress side_split; lia_t1
        | lia_t2
        | lia_t3
        | progress side_split; first [lia_t2 | lia_t3]
        | progress aapp_facts; first [ lia_t1 | progress side_split; lia_t1 | lia_t2 | progress side_split; lia_t2 ]
        | progress side_split_all; lia_t1 ].

